function Example() {
  let [close, setClose] = React.useState(null);

  return (
    <Button
      onPress={() => {
        if (!close) {
          ///- begin highlight -///
          let close = ToastQueue.negative('Unable to save', {onClose: () => setClose(null)});
          ///- end highlight -///
          setClose(() => close);
        } else {
          ///- begin highlight -///
          close();
          ///- end highlight -///
        }
      }}
      variant="primary">
      {close ? 'Hide' : 'Show'} Toast
    </Button>
  );
}
